				$button.addClass([...document.querySelector(`[class*="ant-btn css-"]`).className.match(/css-[a-z0-9]+ css-var-[a-z0-9_]+/g) || []].join(' '));
				$button.find(".pl-dropdown-menu").css({ "top": "34px" });
